   181→  useEffect(() => {
   182→    if (!isLoaded) return
   183→    localStorage.setItem('rise-body-prs', JSON.stringify(bodyPRs))
   184→  }, [bodyPRs, isLoaded])
   185→
   186→  const updateSettings = (newSettings: Partial<UserSettings>) => {
   187→    setSettings(prev => ({ ...prev, ...newSettings }))
   188→  }
   189→
   190→  const addRiseScore = (points: number) => {
   191→    setRiseScore(prev => prev + points)
   192→  }
   193→
   194→  const addMealEntry = (meal: 'breakfast' | 'lunch' | 'dinner' | 'snacks', entry: MealEntry) => {
   195→    setNutrition(prev => ({
   196→      ...prev,
   197→      meals: {
   198→        ...prev.meals,
   199→        [meal]: [...prev.meals[meal], entry],
   200→      },
   201→    }))
   202→  }
   203→
   204→  const removeMealEntry = (meal: 'breakfast' | 'lunch' | 'dinner' | 'snacks', entryId: string) => {
   205→    setNutrition(prev => ({
   206→      ...prev,
   207→      meals: {
   208→        ...prev.meals,
   209→        [meal]: prev.meals[meal].filter(e => e.id !== entryId),
   210→      },
   211→    }))
   212→  }
   213→
   214→  const getTodayTotals = () => {
   215→    const allMeals = [
   216→      ...nutrition.meals.breakfast,
   217→      ...nutrition.meals.lunch,
   218→      ...nutrition.meals.dinner,
   219→      ...nutrition.meals.snacks,
   220→    ]
   221→    return {
   222→      calories: allMeals.reduce((sum, e) => sum + e.calories, 0),
   223→      protein: allMeals.reduce((sum, e) => sum + e.protein, 0),
   224→      carbs: allMeals.reduce((sum, e) => sum + e.carbs, 0),
   225→      fats: allMeals.reduce((sum, e) => sum + e.fats, 0),
   226→    }
   227→  }
   228→
   229→  const addExerciseToDay = (dayIndex: number, exercise: import('./types').Exercise) => {
   230→    setWorkoutSplit(prev => {
   231→      const updated = [...prev]
   232→      updated[dayIndex] = {
   233→        ...updated[dayIndex],
   234→        exercises: [...updated[dayIndex].exercises, exercise],
   235→      }
   236→      return updated
   237→    })
   238→  }
   239→
   240→  const removeExerciseFromDay = (dayIndex: number, exerciseId: string) => {
   241→    setWorkoutSplit(prev => {
   242→      const updated = [...prev]
   243→      updated[dayIndex] = {
   244→        ...updated[dayIndex],
   245→        exercises: updated[dayIndex].exercises.filter(e => e.id !== exerciseId),
   246→      }
   247→      return updated
   248→    })
   249→  }
   250→
   251→  const updateExercise = (dayIndex: number, exerciseId: string, updates: Partial<import('./types').Exercise>) => {
   252→    setWorkoutSplit(prev => {
   253→      const updated = [...prev]
   254→      updated[dayIndex] = {
   255→        ...updated[dayIndex],
   256→        exercises: updated[dayIndex].exercises.map(e =>
   257→          e.id === exerciseId ? { ...e, ...updates } : e
   258→        ),
   259→      }
   260→      return updated
   261→    })
   262→  }
   263→
   264→  const updateQuestProgress = (progress: number) => {
   265→    if (questState && !questState.completed) {
   266→      setQuestState(prev => prev ? { ...prev, progress: Math.min(progress, prev.quest.target) } : null)
   267→    }
   268→  }
   269→
   270→  const completeQuest = () => {
   271→    if (questState && !questState.completed) {
   272→      setQuestState(prev => prev ? { ...prev, completed: true, progress: prev.quest.target } : null)
   273→      addRiseScore(questState.quest.xpReward)
   274→    }
   275→  }
   276→
   277→  const updateBodyPR = (group: keyof BodyChartPRs, exerciseId: string, value: number) => {
   278→    setBodyPRs(prev => ({
   279→      ...prev,
   280→      [group]: {
   281→        ...prev[group],
   282→        [exerciseId]: value,
   283→      },
   284→    }))
   285→  }
   286→
   287→  const resetAllPRs = () => {
   288→    setBodyPRs(getEmptyPRs())
   289→  }
   290→
   291→  return (
   292→    <AppContext.Provider
   293→      value={{
   294→        settings,
   295→        riseScore,
   296→        streak,
   297→        nutrition,
   298→        workoutSplit,
   299→        questState,
   300→        bodyPRs,
   301→        updateSettings,
   302→        addRiseScore,
   303→        addMealEntry,
   304→        removeMealEntry,
   305→        getTodayTotals,
   306→        addExerciseToDay,
   307→        removeExerciseFromDay,
   308→        updateExercise,
   309→        updateQuestProgress,
   310→        completeQuest,
   311→        updateBodyPR,
   312→        resetAllPRs,
   313→      }}
   314→    >
   315→      {children}
   316→    </AppContext.Provider>
   317→  )
   318→}
   319→
   320→export function useApp() {
   321→  const context = useContext(AppContext)
   322→  if (context === undefined) {
   323→    throw new Error('useApp must be used within an AppProvider')
   324→  }
   325→  return context
   326→}
   327→
